def crypt_once(data):
    d=hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def crypt_view(data):
    d=hashes.Hash(hashes.SHA256())
    d.update(memoryview(data))
    return d.finalize()

